onClick:
{{(() => {
    // Use LocationManager validation
    const validation = LocationManager.validateOrderForm();

    if (!validation.isValid) {
        showAlert("Моля, поправете следното:\n" + validation.errors.join("\n"), "error");
        return;
    }

    // Validate service rate selection
    if (!OrderShippingSelect.selectedOptionValue) {
        showAlert("Изберете вид доставка", "error");
        return;
    }

    // The COD amount is optional (Ico, 2026-10-04): none typed = no наложен платеж and no
    // НП fee; the delivery and any declared value still apply. Nothing is asked for here.

    if (DeclaredValueSelect.selectedOptionValue === 'yes') {
        const dv = Number(String(DeclaredValueInput.text || '').trim().replace(',', '.'));
        if (!(dv > 0 && dv <= 5112.92)) {
            showAlert("Въведете обявена стойност до 5 112,92 € (раздел Плащане)", "error");
            return;
        }
    }

    // At least one product, each with weight and size (Ico, 2026-10-02). An item added
    // before this rule has none - the merchant removes it and adds it again.
    const items = appsmith.store.newOrderItems || [];
    if (items.length === 0) {
        showAlert("Добавете поне един артикул с тегло и размери (раздел Артикули)", "error");
        return;
    }
    const unmeasured = items.find((i) => !(i.weight_kg > 0 && i.length_cm > 0 && i.width_cm > 0 && i.height_cm > 0));
    if (unmeasured) {
        showAlert("Артикулът „" + unmeasured.name + "“ няма тегло и размери. Изтрийте го и го добавете отново с тях.", "error");
        return;
    }

    // Standard from tomorrow on, Express from now on, never the past (Ico, 2026-10-02).
    // Checked here so the merchant reads it before anything is sent; the request body
    // and the server apply the same rule.
    const when = ScheduledDeliveryPicker.selectedDate ? moment(ScheduledDeliveryPicker.selectedDate) : null;
    const isExpress = /express/i.test(OrderShippingSelect.selectedOptionLabel || "");
    if (when && when.isBefore(moment().subtract(15, "minutes"))) {
        showAlert("Датата и часът на доставка са в миналото. Изберете бъдещ момент.", "error");
        return;
    }
    if (when && !isExpress && when.isBefore(moment().add(1, "days").startOf("day"))) {
        showAlert("Стандартната доставка е от утре нататък. За доставка днес изберете Експресна.", "error");
        return;
    }

    showAlert("Създаваме поръчката...", "info");

    // One call now. The delivery quote used to be made here first, by two SQL
    // queries writing straight into the production database - and they reused a
    // single quote row for every order placed on the same rate within a day, then
    // never linked it to the order. Fulfilya builds the quote as it creates the
    // order, the same way it does for orders arriving from a shop.
    CreateOrderAPI.run()
        .then((result) => {
            const orderId = result.order_id || "";

            // Our fees on the order, straight away (Ico, 2026-10-02) - the same figures the
            // console box and Детайли show.
            const f = result.fees || (CreateOrderAPI.data || {}).fees || null;
            const eur = (v) => Number(v || 0).toLocaleString('bg-BG', { minimumFractionDigits: 2, maximumFractionDigits: 2 }) + ' €';
            let feesLine = '';
            if (f) {
                const dvf = Number(f.declared_fee) > 0 ? ` · обявена стойност ${eur(f.declared_fee)}` : '';
                feesLine = Number(f.collected) > 0
                    ? `\nСума за събиране ${eur(f.collected)} · доставка ${eur(f.delivery)} · такса НП ${eur(f.cod_fee)}${dvf}`
                    : `\nШофьорът не събира нищо · за фактуриране ${eur(f.invoiced)} (доставка ${eur(f.delivery)}${dvf})`;
            }
            showAlert(`Поръчката е създадена${feesLine}`, "success");

            // Reset form using LocationManager
            LocationManager.resetOrderForm();

            closeModal('CreateOrderModal');

            // Refresh all dashboard data
            GetOrdersList.run();
            GetTotalOrders.run();
            GetOrdersByStatus.run();
            GetDailyOrders.run();
            // The Табло tiles too - they kept the old count until a page reload
            // (found in testing, 2026-10-01).
            BoStats.run();
            BoPayment.run();
            BoStatus.run();
            BoDays.run();
        })
        .catch(err => {
            console.error("Order creation failed:", err, CreateOrderAPI.data, CreateOrderAPI.responseMeta);
            // Fulfilya answers a refused order with a sentence written for a merchant
            // to read, in the response body. err.message is only Appsmith's generic
            // "CreateOrderAPI failed to execute", so read the body first.
            // A login the server no longer knows: the merchant kept yesterday's session
            // and its token was gone, so every order came back "Unauthenticated" while
            // the Табло (read straight from the database) looked fine (TheBasket,
            // 2026-10-02). Say so in their words and take them to the login page.
            const code = Number((CreateOrderAPI.responseMeta || {}).statusCode || 0);
            if (code === 401 || /unauthenticated/i.test(JSON.stringify(CreateOrderAPI.data || ""))) {
                showAlert("Сесията ви изтече. Влезте отново и създайте поръчката пак.", "warning");
                closeModal('CreateOrderModal');
                AuthManager.logout();
                return;
            }
            const body = CreateOrderAPI.data || {};
            const firstField = body.errors ? Object.values(body.errors).flat()[0] : null;
            const reason = body.error || firstField || body.message || err.message || "Please check your input and try again";
            showAlert("Поръчката не беше създадена: " + reason, "error");
        });
})()}}
